<?php

namespace App\Http\Controllers\Api\V1;

use App\Models\{CompanyMembership, GoodsReceipt, GoodsReceiptItem, PurchaseOrder, PurchaseReturn, PurchaseReturnItem, PurchaseReturnShipment, PurchaseReturnShipmentItem, SupplierDebitNote, SupplierRefund, WarehouseLocation};
use App\Services\{AuditLogger, AuthorizationService, ProcurementNumberService, StockMovementService};
use App\Support\{Decimal, TenantContext};
use Illuminate\Http\{JsonResponse, Request};
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\ValidationException;

final class PurchaseReturnController
{
    public function index(Request $request, AuthorizationService $auth): JsonResponse
    {
        $tenant=$this->tenant(); $company=$request->string('company_id')->toString()?:null; $branch=$request->string('branch_id')->toString()?:null; $this->scope($request,$auth,$tenant,$company,$branch);
        $accessible=$company?[$company]:$auth->accessibleCompanyIds($request->user(),$tenant,'procurement.manage');
        $query=PurchaseReturn::where('tenant_id',$tenant)->with(['purchaseOrder.supplier','goodsReceipt','company','branch','items'])->when($accessible!==null,fn($q)=>$q->whereIn('company_id',$accessible))->when($company,fn($q)=>$q->where('company_id',$company))->when($branch,fn($q)=>$q->where('branch_id',$branch))->when($request->filled('supplier_id'),fn($q)=>$q->whereHas('purchaseOrder',fn($po)=>$po->where('supplier_id',$request->string('supplier_id'))))->when($request->filled('search'),function($q)use($request){$s=$request->string('search');$q->where(fn($x)=>$x->where('number','ilike',"%{$s}%")->orWhereHas('purchaseOrder',fn($po)=>$po->where('number','ilike',"%{$s}%"))->orWhereHas('purchaseOrder.supplier',fn($sup)=>$sup->where('name','ilike',"%{$s}%")));})->when($request->filled('approval_status'),fn($q)=>$q->where('approval_status',$request->string('approval_status')))->when($request->filled('shipment_status'),fn($q)=>$q->where('shipment_status',$request->string('shipment_status')))->when($request->filled('date_from'),fn($q)=>$q->whereDate('return_date','>=',$request->date('date_from')))->when($request->filled('date_to'),fn($q)=>$q->whereDate('return_date','<=',$request->date('date_to')));
        $sort=in_array($request->string('sort')->toString(),['number','return_date','approval_status','shipment_status','created_at'],true)?$request->string('sort'):'created_at'; $page=$query->orderBy($sort,$request->string('direction')->toString()==='asc'?'asc':'desc')->paginate(min(max($request->integer('per_page',25),10),100)); $summary=PurchaseReturn::where('tenant_id',$tenant)->when($accessible!==null,fn($q)=>$q->whereIn('company_id',$accessible))->when($company,fn($q)=>$q->where('company_id',$company))->when($branch,fn($q)=>$q->where('branch_id',$branch)); return response()->json(['data'=>$page,'summary'=>['total_returns'=>(clone $summary)->count(),'pending_approval'=>(clone $summary)->where('approval_status','pending')->count(),'dispatched'=>(clone $summary)->where('shipment_status','dispatched')->count(),'awaiting_supplier_credit'=>(clone $summary)->where('supplier_resolution_status','open')->whereIn('approval_status',['approved','posted'])->count(),'open_cases'=>(clone $summary)->where('supplier_resolution_status','open')->count()]]);
    }

    public function store(Request $request, AuthorizationService $auth, ProcurementNumberService $numbers, AuditLogger $audit): JsonResponse
    {
        $tenant=$this->tenant(); $data=$request->validate(['company_id'=>'required|uuid','branch_id'=>'nullable|uuid','purchase_order_id'=>'required|uuid','goods_receipt_id'=>'required|uuid','return_date'=>'required|date','reason'=>'required|in:damaged,defective,wrong_product,incorrect_quantity,quality_rejection,expired,recall,other','reason_detail'=>'nullable|string|max:1000','priority'=>'nullable|in:low,normal,high,urgent','requested_resolution'=>'required|in:supplier_credit,refund,replacement,other','internal_reference'=>'nullable|string|max:100','notes'=>'nullable|string|max:5000','lines'=>'required|array|min:1','lines.*.goods_receipt_item_id'=>'required|uuid','lines.*.quantity'=>['required','regex:/^\d+(\.\d{1,6})?$/'],'lines.*.location_id'=>'required|uuid','lines.*.reason'=>'nullable|string|max:500']); $this->scope($request,$auth,$tenant,$data['company_id'],$data['branch_id']??null);
        $po=PurchaseOrder::where('tenant_id',$tenant)->where('company_id',$data['company_id'])->whereKey($data['purchase_order_id'])->firstOrFail(); $receipt=GoodsReceipt::where('tenant_id',$tenant)->where('company_id',$data['company_id'])->where('purchase_order_id',$po->id)->where('state','posted')->whereKey($data['goods_receipt_id'])->firstOrFail();
        $return=DB::transaction(function()use($data,$tenant,$request,$numbers,$receipt){$ret=PurchaseReturn::create([...$data,'tenant_id'=>$tenant,'number'=>$numbers->makeFor('RET',$tenant,$data['company_id'],$data['branch_id']??null),'created_by'=>$request->user()->id,'state'=>'draft','approval_status'=>'draft','shipment_status'=>'not_prepared','supplier_resolution_status'=>'open','priority'=>$data['priority']??'normal']); foreach($data['lines'] as $line){$ri=GoodsReceiptItem::where('tenant_id',$tenant)->where('goods_receipt_id',$receipt->id)->whereKey($line['goods_receipt_item_id'])->lockForUpdate()->firstOrFail(); if(!$ri->purchase_order_item_id)throw ValidationException::withMessages(['lines'=>['Every return line must reference a purchase-order receipt line.']]); $qty=Decimal::normalize($line['quantity']); $received=(string)($ri->accepted_quantity??$ri->quantity); $already=(string)PurchaseReturnItem::where('tenant_id',$tenant)->where('goods_receipt_item_id',$ri->id)->sum('quantity'); if(Decimal::compare($qty,'0')<=0||Decimal::compare(Decimal::add($already,$qty),$received)>0)throw ValidationException::withMessages(['lines'=>['Return quantity exceeds the eligible quantity on the posted receipt.']]); $location=WarehouseLocation::where('tenant_id',$tenant)->whereKey($line['location_id'])->firstOrFail(); if($receipt->warehouse_id&&$location->warehouse_id!==$receipt->warehouse_id)throw ValidationException::withMessages(['lines'=>['Return location is outside the receipt warehouse.']]); PurchaseReturnItem::create(['tenant_id'=>$tenant,'purchase_return_id'=>$ret->id,'purchase_order_item_id'=>$ri->purchase_order_item_id,'goods_receipt_item_id'=>$ri->id,'variant_id'=>$ri->purchase_order_item->variant_id,'location_id'=>$location->id,'quantity'=>$qty,'unit_cost'=>$ri->purchase_order_item->unit_price,'unit'=>$line['unit']??null,'batch_number'=>$ri->batch_number,'serial_number'=>$ri->serial_number,'reason'=>$line['reason']??$data['reason']]);} return $ret->load('items');}); $audit->record($request,'purchase_return.created',$tenant,$return); return response()->json(['data'=>$return],201);
    }

    public function show(Request $request, PurchaseReturn $purchaseReturn, AuthorizationService $auth): JsonResponse { $tenant=$this->tenant(); abort_unless($purchaseReturn->tenant_id===$tenant,404); $this->scope($request,$auth,$tenant,$purchaseReturn->company_id,$purchaseReturn->branch_id); return response()->json(['data'=>$purchaseReturn->load(['purchaseOrder.supplier','goodsReceipt.items','company','branch','items.variant','shipment.items'])]); }
    public function update(Request $request, PurchaseReturn $purchaseReturn, AuthorizationService $auth, AuditLogger $audit): JsonResponse { $tenant=$this->tenant(); abort_unless($purchaseReturn->tenant_id===$tenant,404); $this->scope($request,$auth,$tenant,$purchaseReturn->company_id,$purchaseReturn->branch_id); abort_unless($purchaseReturn->approval_status==='draft',422); $data=$request->validate(['return_date'=>'date','reason'=>'in:damaged,defective,wrong_product,incorrect_quantity,quality_rejection,expired,recall,other','reason_detail'=>'nullable|string|max:1000','priority'=>'in:low,normal,high,urgent','requested_resolution'=>'in:supplier_credit,refund,replacement,other','notes'=>'nullable|string|max:5000']); $purchaseReturn->update($data); $audit->record($request,'purchase_return.updated',$tenant,$purchaseReturn); return response()->json(['data'=>$purchaseReturn->fresh('items')]); }
    public function submit(Request $request, PurchaseReturn $purchaseReturn, AuthorizationService $auth, AuditLogger $audit): JsonResponse { return $this->transition($request,$purchaseReturn,'pending',$auth,$audit,'purchase_return.submitted'); }
    public function approve(Request $request, PurchaseReturn $purchaseReturn, AuthorizationService $auth, AuditLogger $audit): JsonResponse { abort_unless($auth->allows($request->user(),$this->tenant(),'procurement.approve',$purchaseReturn->company_id,$purchaseReturn->branch_id),403); $purchaseReturn->update(['approval_status'=>'approved','state'=>'approved','approved_by'=>$request->user()->id,'approved_at'=>now()]); $audit->record($request,'purchase_return.approved',$this->tenant(),$purchaseReturn); return response()->json(['data'=>$purchaseReturn->fresh()]); }
    public function reject(Request $request, PurchaseReturn $purchaseReturn, AuthorizationService $auth, AuditLogger $audit): JsonResponse { return $this->transition($request,$purchaseReturn,'rejected',$auth,$audit,'purchase_return.rejected'); }
    public function requestRevision(Request $request, PurchaseReturn $purchaseReturn, AuthorizationService $auth, AuditLogger $audit): JsonResponse { return $this->transition($request,$purchaseReturn,'revision_required',$auth,$audit,'purchase_return.revision_requested'); }

    public function dispatch(Request $request, PurchaseReturn $purchaseReturn, AuthorizationService $auth, StockMovementService $movements, ProcurementNumberService $numbers, AuditLogger $audit): JsonResponse
    {
        $tenant=$this->tenant(); abort_unless($purchaseReturn->tenant_id===$tenant,404); $this->scope($request,$auth,$tenant,$purchaseReturn->company_id,$purchaseReturn->branch_id); abort_unless($purchaseReturn->approval_status==='approved',422); $data=$request->validate(['shipment_date'=>'required|date','carrier'=>'nullable|string|max:100','tracking_reference'=>'nullable|string|max:150','lines'=>'nullable|array','lines.*.purchase_return_item_id'=>'required|uuid','lines.*.quantity'=>['required','regex:/^\d+(\.\d{1,6})?$/']]);
        $result=DB::transaction(function()use($data,$tenant,$request,$purchaseReturn,$movements,$numbers){$ret=PurchaseReturn::where('tenant_id',$tenant)->whereKey($purchaseReturn->id)->lockForUpdate()->with('items')->firstOrFail(); if($ret->shipment_status==='dispatched')return $ret; $ship=PurchaseReturnShipment::create(['tenant_id'=>$tenant,'purchase_return_id'=>$ret->id,'shipment_number'=>$numbers->make('RTS'),'state'=>'dispatched','shipment_date'=>$data['shipment_date'],'carrier'=>$data['carrier']??null,'tracking_reference'=>$data['tracking_reference']??null,'created_by'=>$request->user()->id,'dispatched_by'=>$request->user()->id,'dispatched_at'=>now()]); $lines=$data['lines']??$ret->items->map(fn($i)=>['purchase_return_item_id'=>$i->id,'quantity'=>(string)$i->quantity])->all(); foreach($lines as $line){$item=$ret->items->firstWhere('id',$line['purchase_return_item_id']); if(!$item)throw ValidationException::withMessages(['lines'=>['Shipment line is not part of this return.']]); $qty=Decimal::normalize($line['quantity']); $remaining=Decimal::sub((string)$item->quantity,(string)$item->dispatched_quantity); if(Decimal::compare($qty,'0')<=0||Decimal::compare($qty,$remaining)>0)throw ValidationException::withMessages(['lines'=>['Shipment quantity exceeds the approved return quantity.']]); $movements->post(['tenant_id'=>$tenant,'variant_id'=>$item->variant_id,'location_id'=>$item->location_id,'created_by'=>$request->user()->id,'movement_type'=>'purchase_return','quantity'=>'-'.$qty,'unit_cost'=>$item->unit_cost,'reference_type'=>PurchaseReturn::class,'reference_id'=>$ret->id,'idempotency_key'=>'purchase-return:'.$ret->id.':'.$item->id]); PurchaseReturnShipmentItem::create(['tenant_id'=>$tenant,'shipment_id'=>$ship->id,'purchase_return_item_id'=>$item->id,'quantity'=>$qty]); $item->update(['dispatched_quantity'=>Decimal::add((string)$item->dispatched_quantity,$qty)]);} $ret->update(['shipment_status'=>'dispatched','state'=>'posted','dispatched_by'=>$request->user()->id,'dispatched_at'=>now()]); return $ret->fresh('items');}); $audit->record($request,'purchase_return.dispatched',$tenant,$result); return response()->json(['data'=>$result]);
    }

    public function debitNotes(Request $request, PurchaseReturn $purchaseReturn, AuthorizationService $auth, ProcurementNumberService $numbers, AuditLogger $audit): JsonResponse { $tenant=$this->tenant(); abort_unless($purchaseReturn->tenant_id===$tenant,404); $this->scope($request,$auth,$tenant,$purchaseReturn->company_id,$purchaseReturn->branch_id); $d=$request->validate(['currency_id'=>'required|uuid','document_date'=>'required|date','reason'=>'required|string|max:500','total'=>['required','regex:/^\d+(\.\d{1,6})?$/'],'tax_adjustment'=>'nullable|regex:/^\d+(\.\d{1,6})?$/']); $note=SupplierDebitNote::create([...$d,'tenant_id'=>$tenant,'company_id'=>$purchaseReturn->company_id,'branch_id'=>$purchaseReturn->branch_id,'supplier_id'=>$purchaseReturn->purchaseOrder->supplier_id,'purchase_return_id'=>$purchaseReturn->id,'number'=>$numbers->make('SDN'),'state'=>'draft','created_by'=>$request->user()->id]); $audit->record($request,'supplier_debit.created',$tenant,$note); return response()->json(['data'=>$note],201); }
    public function refunds(Request $request, PurchaseReturn $purchaseReturn, AuthorizationService $auth, AuditLogger $audit): JsonResponse { $tenant=$this->tenant(); abort_unless($purchaseReturn->tenant_id===$tenant,404); $this->scope($request,$auth,$tenant,$purchaseReturn->company_id,$purchaseReturn->branch_id); $d=$request->validate(['currency_id'=>'required|uuid','reference'=>'required|string|max:100','refund_date'=>'required|date','amount'=>['required','regex:/^\d+(\.\d{1,6})?$/'],'bank_account_id'=>'nullable|uuid','transaction_reference'=>'nullable|string|max:150','notes'=>'nullable|string|max:1000']); $refund=SupplierRefund::create([...$d,'tenant_id'=>$tenant,'company_id'=>$purchaseReturn->company_id,'supplier_id'=>$purchaseReturn->purchaseOrder->supplier_id,'purchase_return_id'=>$purchaseReturn->id,'verification_status'=>'unverified','created_by'=>$request->user()->id]); $audit->record($request,'supplier_refund.created',$tenant,$refund); return response()->json(['data'=>$refund],201); }
    private function transition(Request $request, PurchaseReturn $return, string $status, AuthorizationService $auth, AuditLogger $audit, string $action): JsonResponse { $tenant=$this->tenant(); abort_unless($return->tenant_id===$tenant,404); $this->scope($request,$auth,$tenant,$return->company_id,$return->branch_id); abort_unless(in_array($return->approval_status,['draft','pending','revision_required'],true),422); $return->update(['approval_status'=>$status,'state'=>$status==='pending'?'pending_approval':$status]); $audit->record($request,$action,$tenant,$return); return response()->json(['data'=>$return->fresh()]); }
    private function scope(Request $request, AuthorizationService $auth, string $tenant, ?string $company, ?string $branch=null): void { if($company){abort_unless($auth->allows($request->user(),$tenant,'procurement.manage',$company,$branch),403); abort_unless(CompanyMembership::where('tenant_id',$tenant)->where('company_id',$company)->where('user_id',$request->user()->id)->where('status','active')->exists(),403);}}
    private function tenant(): string { return (string)app(TenantContext::class)->id(); }
    public function post(Request $request, PurchaseOrder $purchaseOrder, StockMovementService $movements, ProcurementNumberService $numbers, AuthorizationService $authorization, AuditLogger $audit): JsonResponse { abort_unless($purchaseOrder->tenant_id===$this->tenant(),404); abort_unless($authorization->allows($request->user(),$this->tenant(),'procurement.manage'),403); throw ValidationException::withMessages(['workflow'=>['Direct purchase-return posting is disabled. Create a return, obtain approval, then dispatch it.']]); }
}
